{
  "name": "where-am-i",
  "version": "0.1.0",
  "description": "Shows which machine and repo a session runs in (Mac or the claude-code container, repo, branch, fork) in the status line, and nudges Claude when it reaches for the container from the Mac or runs a repo's tests on the wrong host.",
  "author": {
    "name": "David Coulson",
    "url": "https://github.com/davidcoulson"
  },
  "userConfig": {
    "hosts": {
      "type": "string",
      "multiple": true,
      "title": "Host labels",
      "description": "hostname-glob=label pairs, first match wins, e.g. claude-code*=🐧 claude-code. Unmatched: 🍎 Mac on macOS, 🐳 <host> in a container, 🐧 <host> elsewhere.",
      "default": []
    },
    "homes": {
      "type": "string",
      "multiple": true,
      "title": "Where each repo's dev work runs",
      "description": "repo-glob=mac|container pairs. Running a build or test of a matching repo on the other kind of host adds a note for Claude. Example: my-integration=container, my-app-*=mac.",
      "default": []
    },
    "containerTargets": {
      "type": "string",
      "multiple": true,
      "title": "SSH targets that mean the dev container or Unraid host",
      "description": "Words that, after ssh/scp/rsync on the Mac, mean work that belongs in an SSH session on that host instead. Example: my-nas, dev-box, 192.168.1.20.",
      "default": []
    }
  },
  "license": "MIT"
}
